[{"order":1,"type":"heading","text":"Spring Cloud: Config Server, Service Discovery, and API Gateway"},{"order":2,"type":"paragraph","text":"Spring Cloud builds on Spring Boot and provides tools for developers to quickly build some of the common patterns in distributed systems (e.g., configuration management, service discovery, circuit breakers, intelligent routing, micro-proxy, control bus, global locks, leadership election, distributed sessions, cluster state). This tutorial provides an overview of three core Spring Cloud components: Config Server, Service Discovery (using Eureka), and API Gateway (using Spring Cloud Gateway)."},{"order":3,"type":"heading","text":"1. Spring Cloud Config Server"},{"order":4,"type":"paragraph","text":"The Spring Cloud Config Server provides externalized configuration in a distributed system. With the Config Server, you have a central place to manage external properties for applications across all environments. Client applications bootstrap themselves with the location of the Config Server and then retrieve their configuration from it. This approach decouples configuration from code, making applications more portable and easier to manage."},{"order":5,"type":"subheading","text":"1.1 Setting up the Config Server"},{"order":6,"type":"paragraph","text":"First, create a new Spring Boot project using Spring Initializr (start.spring.io). Include the 'Config Server' dependency. You will also need 'Web' dependency to expose the configuration via HTTP."},{"order":7,"type":"code","text":"<!-- pom.xml -->
<dependencies>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-config-server</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
	<dependency>
		<groupId>org.springframework.cloud</groupId>
		<artifactId>spring-cloud-starter-bootstrap</artifactId>
	</dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-test</artifactId>
        <scope>test</scope>
    </dependency>
</dependencies>

<dependencyManagement>
    <dependencies>
        <dependency>
            <groupId>org.springframework.cloud</groupId>
            <artifactId>spring-cloud-dependencies</artifactId>
            <version>${spring-cloud.version}</version>
            <type>pom</type>
            <scope>import</scope>
        </dependency>
    </dependencies>
</dependencyManagement>"},{"order":8,"type":"paragraph","text":"Next, annotate your main application class with `@EnableConfigServer`."},{"order":9,"type":"code","text":"// ConfigServerApplication.java

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.config.server.EnableConfigServer;

@SpringBootApplication
@EnableConfigServer
public class ConfigServerApplication {

    public static void main(String[] args) {
        SpringApplication.run(ConfigServerApplication.class, args);
    }

}"},{"order":10,"type":"paragraph","text":"Configure the Config Server's properties in `application.properties` or `application.yml`.  You'll need to specify the source of the configuration.  A common approach is to use a Git repository."},{"order":11,"type":"code","text":"# application.properties
spring.application.name=config-server
server.port=8888
spring.cloud.config.server.git.uri=https://github.com/your-username/your-config-repo
spring.cloud.config.server.git.username=your-github-username
spring.cloud.config.server.git.password=your-github-token
spring.cloud.config.server.git.default-label=main"},{"order":12,"type":"paragraph","text":"Replace `https://github.com/your-username/your-config-repo` with the URL of your Git repository. Create a Git repository with configuration files for your applications. These files should be named according to the pattern `{application}-{profile}.properties` or `{application}-{profile}.yml`. For example, `my-app-dev.properties` or `my-app-prod.yml`."},{"order":13,"type":"subheading","text":"1.2 Configuring a Client Application"},{"order":14,"type":"paragraph","text":"Create a new Spring Boot application. Add the `spring-cloud-starter-config` dependency."},{"order":15,"type":"code","text":"<!-- pom.xml -->
<dependencies>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-starter-config</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
	<dependency>
		<groupId>org.springframework.cloud</groupId>
		<artifactId>spring-cloud-starter-bootstrap</artifactId>
	</dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-test</artifactId>
        <scope>test</scope>
    </dependency>
</dependencies>

<dependencyManagement>
    <dependencies>
        <dependency>
            <groupId>org.springframework.cloud</groupId>
            <artifactId>spring-cloud-dependencies</artifactId>
            <version>${spring-cloud.version}</version>
            <type>pom</type>
            <scope>import</scope>
        </dependency>
    </dependencies>
</dependencyManagement>"},{"order":16,"type":"paragraph","text":"Create a `bootstrap.properties` (or `bootstrap.yml`) file in the `src/main/resources` directory. This file is used to configure the application before the main `application.properties` (or `application.yml`) is loaded.  It's crucial for pointing the application to the Config Server."},{"order":17,"type":"code","text":"# bootstrap.properties
spring.application.name=my-app
spring.cloud.config.uri=http://localhost:8888"},{"order":18,"type":"paragraph","text":"Replace `my-app` with the name of your application (as used in the configuration files in the Git repository). Replace `http://localhost:8888` with the address of your Config Server."},{"order":19,"type":"paragraph","text":"Now, you can inject properties from the Config Server into your application using `@Value` or `@ConfigurationProperties`."},{"order":20,"type":"code","text":"// MyController.java

import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class MyController {

    @Value("${my.property:default_value}")
    private String myProperty;

    @GetMapping("/property")
    public String getProperty() {
        return "The value of my.property is: " + myProperty;
    }
}"},{"order":21,"type":"paragraph","text":"If `my.property` is defined in the configuration files in the Git repository, its value will be injected into `myProperty`. Otherwise, the default value `default_value` will be used."},{"order":22,"type":"heading","text":"2. Service Discovery with Eureka"},{"order":23,"type":"paragraph","text":"Service Discovery is a key component in a microservices architecture. It allows services to locate each other dynamically without hardcoding URLs. Spring Cloud integrates with Netflix Eureka for service discovery. Eureka consists of a server (the Eureka Server) and clients (the Eureka Clients, which are your microservices)."},{"order":24,"type":"subheading","text":"2.1 Setting up the Eureka Server"},{"order":25,"type":"paragraph","text":"Create a new Spring Boot project using Spring Initializr. Include the 'Eureka Server' dependency."},{"order":26,"type":"code","text":"<!-- pom.xml -->
<dependencies>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-starter-netflix-eureka-server</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
	<dependency>
		<groupId>org.springframework.cloud</groupId>
		<artifactId>spring-cloud-starter-bootstrap</artifactId>
	</dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-test</artifactId>
        <scope>test</scope>
    </dependency>
</dependencies>

<dependencyManagement>
    <dependencies>
        <dependency>
            <groupId>org.springframework.cloud</groupId>
            <artifactId>spring-cloud-dependencies</artifactId>
            <version>${spring-cloud.version}</version>
            <type>pom</type>
            <scope>import</scope>
        </dependency>
    </dependencies>
</dependencyManagement>"},{"order":27,"type":"paragraph","text":"Annotate your main application class with `@EnableEurekaServer`."},{"order":28,"type":"code","text":"// EurekaServerApplication.java

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.netflix.eureka.server.EnableEurekaServer;

@SpringBootApplication
@EnableEurekaServer
public class EurekaServerApplication {

    public static void main(String[] args) {
        SpringApplication.run(EurekaServerApplication.class, args);
    }

}"},{"order":29,"type":"paragraph","text":"Configure the Eureka Server in `application.properties` or `application.yml`."},{"order":30,"type":"code","text":"# application.properties
spring.application.name=eureka-server
server.port=8761
eureka.client.register-with-eureka=false
eureka.client.fetch-registry=false"},{"order":31,"type":"paragraph","text":"`eureka.client.register-with-eureka=false` and `eureka.client.fetch-registry=false` prevent the Eureka Server from trying to register itself as a client."},{"order":32,"type":"subheading","text":"2.2 Configuring a Eureka Client"},{"order":33,"type":"paragraph","text":"Create a new Spring Boot application. Include the 'Eureka Discovery Client' dependency."},{"order":34,"type":"code","text":"<!-- pom.xml -->
<dependencies>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-starter-netflix-eureka-client</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-web</artifactId>
    </dependency>
	<dependency>
		<groupId>org.springframework.cloud</groupId>
		<artifactId>spring-cloud-starter-bootstrap</artifactId>
	</dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-test</artifactId>
        <scope>test</scope>
    </dependency>
</dependencies>

<dependencyManagement>
    <dependencies>
        <dependency>
            <groupId>org.springframework.cloud</groupId>
            <artifactId>spring-cloud-dependencies</artifactId>
            <version>${spring-cloud.version}</version>
            <type>pom</type>
            <scope>import</scope>
        </dependency>
    </dependencies>
</dependencyManagement>"},{"order":35,"type":"paragraph","text":"Annotate your main application class with `@EnableDiscoveryClient`."},{"order":36,"type":"code","text":"// MyServiceApplication.java

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;

@SpringBootApplication
@EnableDiscoveryClient
public class MyServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(MyServiceApplication.class, args);
    }

}"},{"order":37,"type":"paragraph","text":"Configure the Eureka Client in `application.properties` or `application.yml`."},{"order":38,"type":"code","text":"# application.properties
spring.application.name=my-service
server.port=8080
eureka.client.service-url.defaultZone=http://localhost:8761/eureka"},{"order":39,"type":"paragraph","text":"Replace `http://localhost:8761/eureka` with the address of your Eureka Server. The `spring.application.name` is the service ID that other services will use to find this service."},{"order":40,"type":"paragraph","text":"You can now use the `DiscoveryClient` to look up other services.  Alternatively, you can use the `@LoadBalanced` annotation with the `RestTemplate` to automatically resolve service names."},{"order":41,"type":"code","text":"// MyController.java

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cloud.client.ServiceInstance;
import org.springframework.cloud.client.discovery.DiscoveryClient;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestTemplate;
import org.springframework.cloud.client.loadbalancer.LoadBalanced;
import org.springframework.context.annotation.Bean;

import java.util.List;

@RestController
public class MyController {

    @Autowired
    private DiscoveryClient discoveryClient;

    @Autowired
    private RestTemplate restTemplate;

    @GetMapping("/call-service")
    public String callService() {
        List<ServiceInstance> instances = discoveryClient.getInstances("another-service");
        if (instances != null && !instances.isEmpty()) {
            ServiceInstance instance = instances.get(0);
            String url = instance.getUri().toString();
            return restTemplate.getForObject(url + "/hello", String.class);
        }
        return "Service not available";
    }

    @Bean
    @LoadBalanced
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }
}"},{"order":42,"type":"paragraph","text":"In this example, `another-service` is the `spring.application.name` of the service you want to call. The `@LoadBalanced` annotation enables the `RestTemplate` to resolve service names using Eureka."},{"order":43,"type":"heading","text":"3. API Gateway with Spring Cloud Gateway"},{"order":44,"type":"paragraph","text":"An API Gateway acts as a single entry point for all client requests. It can handle routing, authentication, authorization, rate limiting, and other cross-cutting concerns. Spring Cloud Gateway provides a flexible and powerful way to build API Gateways using Spring WebFlux."},{"order":45,"type":"subheading","text":"3.1 Setting up the API Gateway"},{"order":46,"type":"paragraph","text":"Create a new Spring Boot project using Spring Initializr. Include the 'Cloud Gateway' and 'Eureka Discovery Client' dependencies. The latter is optional, but useful if you want the gateway to use service discovery."},{"order":47,"type":"code","text":"<!-- pom.xml -->
<dependencies>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-starter-gateway</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.cloud</groupId>
        <artifactId>spring-cloud-starter-netflix-eureka-client</artifactId>
    </dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-webflux</artifactId>
    </dependency>
	<dependency>
		<groupId>org.springframework.cloud</groupId>
		<artifactId>spring-cloud-starter-bootstrap</artifactId>
	</dependency>
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-test</artifactId>
        <scope>test</scope>
    </dependency>
</dependencies>

<dependencyManagement>
    <dependencies>
        <dependency>
            <groupId>org.springframework.cloud</groupId>
            <artifactId>spring-cloud-dependencies</artifactId>
            <version>${spring-cloud.version}</version>
            <type>pom</type>
            <scope>import</scope>
        </dependency>
    </dependencies>
</dependencyManagement>"},{"order":48,"type":"paragraph","text":"Configure the Gateway in `application.properties` or `application.yml`. You can define routes that map incoming requests to backend services."},{"order":49,"type":"code","text":"# application.yml
spring:
  application:
    name: api-gateway
  cloud:
    gateway:
      routes:
        - id: my-service-route
          uri: lb://my-service
          predicates:
            - Path=/my-service/**
          filters:
            - RewritePath=/my-service/(?<segment>.*), /$\{segment}"},{"order":50,"type":"paragraph","text":"In this example:

*   `id`: A unique identifier for the route.
*   `uri`: The URI of the backend service. `lb://my-service` uses the LoadBalancerClient (integrated with Eureka) to resolve the `my-service` service name.
*   `predicates`: Conditions that must be met for the route to be matched. In this case, any request with a path starting with `/my-service/` will be routed.
*   `filters`: Filters that modify the request or response. `RewritePath` removes the `/my-service` prefix from the path before forwarding the request to the backend service."},{"order":51,"type":"paragraph","text":"You can also define routes programmatically using Java configuration."},{"order":52,"type":"code","text":"// GatewayConfig.java

import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class GatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
                .route("path_route", r -> r.path("/get")
                        .uri("http://httpbin.org"))
                .route("my_service_route", r -> r.path("/my-service/**")
                        .filters(f -> f.rewritePath("/my-service/(?<segment>.*)", "/$\{segment}"))
                        .uri("lb://my-service"))
                .build();
    }
}"},{"order":53,"type":"paragraph","text":"This code defines two routes: one that routes requests to `/get` to `http://httpbin.org`, and another that routes requests to `/my-service/**` to the `my-service` service (using service discovery)."},{"order":54,"type":"heading","text":"Conclusion"},{"order":55,"type":"paragraph","text":"Spring Cloud provides a powerful set of tools for building distributed systems. The Config Server, Service Discovery (Eureka), and API Gateway (Spring Cloud Gateway) are essential components for managing configuration, discovering services, and routing requests in a microservices architecture. This tutorial provided a basic overview of these components and how to set them up. Further exploration of Spring Cloud's features and capabilities is highly recommended for building robust and scalable applications."}]
